import React from 'react';
import './SignUp.css';
import { useNavigate } from 'react-router-dom';
import { useState } from 'react';
import { checkForm } from './validate.js';


function SignUp({usersList, setUsersList}) {
    const navigate = useNavigate();

    const [firstName, setFirstName] = useState('');
    const [lastName, setLastName] = useState('');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [ConfirmedPassword, setConfirmedPassword] = useState('');
    const [picture, setPicture] = useState('');



    const handleCloseClick = () => {
        // Navigate to the login page
        navigate('/');
    };

    const handleSignUpClick = () => {

        // Check if the form is valid
        const requiredElements = document.querySelectorAll('[required]');
        const isValid = checkForm(requiredElements, usersList={usersList});

        if (isValid) {
            const newUserId = usersList.length + 1;
            const user = {id: newUserId,
                 firstName: firstName, 
                 lastName: lastName, 
                 displayName: firstName + ' ' + lastName,
                 email: email, 
                 password: password, 
                 picture: picture};
                 setUsersList(prevUsersList => [...prevUsersList, user]);
                 navigate('/');
        }
    };





    


    

    return (
        < div className="SIform" noValidate>
            <button id="close" type="button" className="btn-close" onClick={handleCloseClick} aria-label="Close"></button>
            <div className="headLine">
                <p id="first">Sign Up</p>
                <p id="second">It's quick and easy.</p>
            </div>
            

            <div className="container text">
                <div className="row">
                    <div className="col">
                        <div className="mb-3">
                            <div className="input-group">
                                <input type="firstName"
                                    className="form-control"
                                    id="InputFirstName"
                                    placeholder="First name"
                                    aria-describedby="inputGroupPrepend"
                                    value={firstName}
                                    onChange={(e) => setFirstName(e.target.value)}
                                    required>
                                </input>
                            </div>
                        </div>
                    </div>
                    <div className="col">
                        <div className="mb-3">
                            <div className="input-group">
                                <input type="lastName"
                                    className="form-control"
                                    id="InputLastName"
                                    placeholder="Last name"
                                    aria-describedby="inputGroupPrepend"
                                    value={lastName}
                                    onChange={(e) => setLastName(e.target.value)}
                                    required>
                                </input>
                            </div>
                        </div>
                    </div>
                </div>


                <div className="mb-3">
                    <div className="input-group">
                        <input type="EmailOrNumber"
                            className="form-control"
                            id="InputEmail"
                            placeholder="Mobile number or email"
                            aria-describedby="inputGroupPrepend"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            required>
                        </input>
                    </div>
                </div>
                <div className="mb-3">
                    <input type="password" className="form-control" id="InputPassword" placeholder="New Password"
                        aria-describedby="inputGroupPrepend"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        required>
                    </input>
                </div>

                <div className="mb-3">
                    <input type="password" className="form-control" id="ConfirmedPassword" placeholder="Confirm Password"
                        aria-describedby="inputGroupPrepend"
                        value={ConfirmedPassword}
                        onChange={(e) => setConfirmedPassword(e.target.value)}
                        required>
                    </input>
                </div>
                <p>* first name and last name must contain only letters</p>
                <p>* password must contain at least 8 characters, including a letter, number and a special character</p>
                
            



                <p id="pic">picture</p>
                <div className="mb-3">
                    <input className="form-control" type="file" id="formFile"
                        aria-describedby="inputGroupPrepend"
                        onChange={(e) => setPicture(e.target.files[0])}
                        required
                    />
                </div>
            

                <div id="signUpBtn">
                    <button type="submit" className="btn btn-primary" onClick={handleSignUpClick}>Sign Up</button>
                </div>
            </div>
        </div>


    );
}

                export default SignUp;
